<?phpnamespace Nemundo\App\Scheduler\Site;use Nemundo\App\Scheduler\Page\RunningPage;use Nemundo\Web\Site\AbstractSite;class RunningSite extends AbstractSite{    /**     * @var RunningSite     */    public static $site;    protected function loadSite()    {        $this->title = 'Running';        $this->url = 'running';        new SchedulerResetSite($this);        RunningSite::$site = $this;    }    public function loadContent()    {        (new RunningPage())->render();    }}